// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b PostUpdate) exec() !int {
	client, span := b.graph.client.start_span(.default, 'update posts', 'posts', 'update')
	defer {
		span.end()
	}
	result := PostUpdate{
		...b
		graph: Graph{
			client: client
		}
	}.exec_untraced() or {
		vgraph.span_failed(span, err)
		return err
	}
	vgraph.span_rows(span, result)
	return result
}

// exec_untraced is `exec`, without its span.
fn (b PostUpdate) exec_untraced() !int {
	return b.graph.client.update(b.data)
}

// PostDeleteOne builds the delete of one `posts` row. Start one with
